/* XRE Bitrix Rapor v2 — saf JavaScript; ağ, dosya sistemi ve dış modül kullanmaz.
 * Bitrix çağrıları yalnızca n8n HTTP Request düğümünden yapılır.
 * Kaynak iş akışının CRM_TODO ve lead kapsamı korunmuştur.
 */
const XRE = (() => {
  'use strict';
  const VERSION = '2.0.0';
  const TZ = 'Europe/Istanbul';
  const DAY = 86400000;
  const READ_METHODS = ['user.get', 'crm.status.list', 'crm.lead.fields', 'crm.activity.fields', 'crm.activity.list', 'crm.lead.list', 'voximplant.statistic.get'];
  const CALL_KEYS = ['d_arama', 'd_giden', 'd_gelen', 'd_callback', 'd_bilgilendirme', 'd_yon_belirsiz', 'd_cevaplanan', 'd_gecerli', 'd_giden_gecerli', 'd_kisa', 'd_cevapsiz', 'd_reddedilen', 'd_iptal', 'd_mesgul', 'd_diger_hata', 'd_sonuc_belirsiz', 'd_konusma_sn', 'd_ortalama_sn'];
  const METRICS = {
    d_olusturdugu: 'Rapor gününde oluşturduğu CRM yapılacak işi',
    d_tamamlanmis_guncellenen: 'Rapor gününde güncellenen, şimdi tamamlanmış ve sorumlusu kendisi olan iş',
    d_olusturup_acik: 'Rapor gününde oluşturduğu, sorgu anında açık iş',
    d_vadesi_gelen: 'Rapor gününün tamamında vadesi olan iş',
    d_vadesi_acik: 'Rapor gününde vadesi olan, sorgu anında açık iş',
    d_gun_ici_unutulan: 'Rapor gününde vadesi olay kesiminden önce dolmuş, hâlâ açık iş (tamamlamayı unuttu)',
    t_etkinlik: 'Rapor günü dahil yapılandırılan takvim aralığında oluşturduğu iş',
    t_acik: 'Sorgu anında üzerinde açık iş',
    t_geciken: 'Sorgu anında açık; vadesi olay kesiminden önce',
    t_onceki_gun_geciken: 'Sorgu anında açık; vadesi rapor gününden önce',
    d_randevu_son_hareket: 'Şimdi randevu aşamasında; son aşama hareketi rapor gününde ve taşıyanı kendisi',
    t_rand_portfoy: 'Sorgu anında randevu aşamasında ve sorumlusu kendisi olan lead',
    t_rand_son_hareket: 'Şimdi randevu aşamasında; son aşama hareketi yapılandırılan takvim aralığında ve taşıyanı kendisi',
    d_satis_asamasi_son_hareket: 'Şimdi yapılandırılmış satış aşamasında; son hareketi rapor gününde ve taşıyanı kendisi',
    t_satis_asamasi: 'Şimdi yapılandırılmış satış aşamasında; son taşıyanı kendisi olan lead',
    d_donusen_son_hareket: 'Şimdi CONVERTED; son hareketi rapor gününde ve taşıyanı kendisi',
    t_donusen: 'Şimdi CONVERTED; son taşıyanı kendisi olan lead',
    t_arama: 'Rapor günü dahil yapılandırılan takvim aralığının arama kayıt sayısı'
  };
  const clone = x => JSON.parse(JSON.stringify(x));
  const own = (o,k) => Object.prototype.hasOwnProperty.call(o || {},k);
  const unique = xs => [...new Set(xs)];
  const posId = v => /^\d+$/.test(String(v)) && Number(v) > 0;
  const nonNegInt = v => (typeof v === 'number' || (typeof v === 'string' && /^\d+$/.test(v))) && Number.isSafeInteger(Number(v)) && Number(v) >= 0;
  const numeric = v => v !== null && v !== '' && v !== undefined && typeof v !== 'boolean' && Number.isFinite(Number(v));
  function dateTR(iso) {
    const parts = new Intl.DateTimeFormat('en-CA', {timeZone: TZ, year:'numeric', month:'2-digit', day:'2-digit'}).formatToParts(new Date(iso));
    const p = Object.fromEntries(parts.map(x=>[x.type,x.value]));
    return `${p.year}-${p.month}-${p.day}`;
  }
  function validDay(s) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
    const t = Date.parse(s+'T12:00:00Z');
    return Number.isFinite(t) && new Date(t).toISOString().slice(0,10) === s;
  }
  function shiftDay(s,n) { return new Date(Date.parse(s+'T12:00:00Z')+n*DAY).toISOString().slice(0,10); }
  function time(iso) {
    if (typeof iso !== 'string' || !/(?:Z|[+-]\d\d:\d\d)$/.test(iso)) return null;
    const x = Date.parse(iso); return Number.isFinite(x) ? x : null;
  }
  function validateSettings(c) {
    if (!c || typeof c !== 'object') throw new Error('Ayarlar nesnesi bulunamadı.');
    if (!/^https:\/\/xre\.bitrix24\.com\.tr\/rest\/\d+\/[A-Za-z0-9_-]+\/$/.test(c.bitrixWebhookBase || '') || /YENI_WEBHOOK|DEGISTIR|PLACEHOLDER/.test(c.bitrixWebhookBase)) {
      throw new Error('Ayarlar: bitrixWebhookBase alanına yeni Bitrix webhook ana adresini, sondaki / işaretiyle girin. Gizli anahtar hata mesajına yazılmadı.');
    }
    for (const k of ['telegramGonder','epostaGonder','kapsamOnaylandi','asamaEslesmeleriOnaylandi','eksikVeriyleGonder']) {
      if (typeof c[k] !== 'boolean') throw new Error(`Ayarlar: ${k} true/false olmalı.`);
    }
    if (!Array.isArray(c.personeller) || !c.personeller.length) throw new Error('Personel kapsamı boş olamaz.');
    const ids = c.personeller.map(p=>String(p.user_id));
    if (ids.some(id=>!posId(id)) || unique(ids).length !== ids.length) throw new Error('Personel ID listesinde geçersiz/tekrarlanan değer var.');
    if (c.activityProvider !== 'CRM_TODO') throw new Error('Bu sürüm kaynak akıştaki CRM_TODO kapsamı için hazırlanmıştır. Diğer sağlayıcılar ayrıca doğrulanmalı.');
    if (c.personeller.some(p=>!String(p.user_name || '').trim())) throw new Error('Personel adı boş olamaz.');
    for (const k of ['randevuAsamalari','satisAsamalari','donusumAsamalari']) {
      if (!Array.isArray(c[k]) || !c[k].length || c[k].some(x=>!/^[A-Za-z0-9_:.-]{1,80}$/.test(String(x)))) throw new Error(`Ayarlar: ${k} boş/geçersiz.`);
    }
    const all = [...c.randevuAsamalari,...c.satisAsamalari,...c.donusumAsamalari];
    if (unique(all).length !== all.length) throw new Error('Aşama grupları çakışamaz. CONVERTED satış grubuna dahil edilmemeli.');
    if (c.satisAsamalari.includes('CONVERTED')) throw new Error('CONVERTED, satış değildir; dönüşüm grubunda tutulmalı.');
    for (const [key,lo,hi] of [['gunSayisi',1,366],['maxPagesPerJob',1,2000],['maxRequests',1,20000],['maxAttempts',1,8],['requestIntervalSeconds',1,60]]) {
      if (!nonNegInt(c[key]) || Number(c[key])<lo || Number(c[key])>hi) throw new Error(`Ayarlar: ${key} ${lo}-${hi} aralığında tamsayı olmalı.`);
    }
    if (!/^-?\d+$/.test(String(c.telegramChatId))) throw new Error('Telegram chat ID sayısal olmalı.');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(c.epostaAlici))) throw new Error('E-posta alıcısı geçersiz.');
    return true;
  }
  function createState(cfg, nowISO) {
    validateSettings(cfg);
    const c = clone(cfg); delete c.bitrixWebhookBase;
    const now = new Date(nowISO || Date.now()).toISOString();
    const today = dateTR(now), day = c.raporGunu || today;
    // +03:00 sabitliği için modern dönem; önceki yıllar ayrıca saat dilimi hesabı gerektirir.
    if (!validDay(day) || day < '2017-01-01' || day > today) throw new Error('Rapor günü 2017-01-01 ile bugün arasında YYYY-MM-DD olmalı.');
    const next = shiftDay(day,1), start = day+'T00:00:00+03:00', end = next+'T00:00:00+03:00';
    const cutoff = new Date(Math.min(Date.parse(now),Date.parse(end))).toISOString();
    const range = {day, dayStart:start, dayEnd:end, cutoff, start30:shiftDay(day,1-c.gunSayisi)+'T00:00:00+03:00', collectedFrom:now, collectedTo:null, historical:day!==today};
    const people = c.personeller.map(p=>({user_id:String(p.user_id), user_name:String(p.user_name).trim().slice(0,100), configured_name:String(p.user_name).trim().slice(0,100), verified:false, active:null, metrics:{}, calls:null}));
    const s = {version:VERSION, config:c, range, people, meta:{}, jobs:[], jobIndex:0, current:null, done:false, requestCount:0, retryCount:0, waitSeconds:0, blockedMethods:{}, fatal:null, audit:[], warnings:[]};
    const add = j => s.jobs.push({...j, index:s.jobs.length});
    add({key:'users', method:'user.get', mode:'users', body:{FILTER:{'@ID':people.map(p=>p.user_id)}, select:['ID','NAME','LAST_NAME','ACTIVE'], sort:'ID', order:'ASC'}});
    add({key:'stages', method:'crm.status.list', mode:'stages', body:{filter:{ENTITY_ID:'STATUS'}, order:{SORT:'ASC'}}});
    add({key:'leadFields', method:'crm.lead.fields', mode:'fields', body:{}});
    add({key:'activityFields', method:'crm.activity.fields', mode:'fields', body:{}});
    const af = ['ID','AUTHOR_ID','RESPONSIBLE_ID','PROVIDER_ID','CREATED','LAST_UPDATED','COMPLETED','DEADLINE'];
    const lf = ['ID','STATUS_ID','ASSIGNED_BY_ID','MOVED_BY_ID','MOVED_TIME'];
    for (const p of people) {
      const uid=p.user_id;
      add({userId:uid,key:'dailyCalls',method:'voximplant.statistic.get',mode:'calls',body:{FILTER:{PORTAL_USER_ID:uid, '>=CALL_START_DATE':start, '<CALL_START_DATE':cutoff},SORT:'ID',ORDER:'ASC'}});
      add({userId:uid,key:'t_arama',method:'voximplant.statistic.get',mode:'count',body:{FILTER:{PORTAL_USER_ID:uid, '>=CALL_START_DATE':range.start30, '<CALL_START_DATE':cutoff},SORT:'ID',ORDER:'ASC'}});
      function act(key,filter){add({userId:uid,key,method:'crm.activity.list',mode:'count',requires:'activityFields',body:{filter:{PROVIDER_ID:c.activityProvider,...filter},select:af,order:{ID:'ASC'}}});}
      const createdDay = {AUTHOR_ID:uid,'>=CREATED':start,'<CREATED':cutoff};
      const dueDay = {RESPONSIBLE_ID:uid,'>=DEADLINE':start,'<DEADLINE':end};
      act('d_olusturdugu',createdDay);
      act('d_tamamlanmis_guncellenen',{RESPONSIBLE_ID:uid,COMPLETED:'Y','>=LAST_UPDATED':start,'<LAST_UPDATED':cutoff});
      act('d_olusturup_acik',{...createdDay,COMPLETED:'N'});
      act('d_vadesi_gelen',dueDay);
      act('d_vadesi_acik',{...dueDay,COMPLETED:'N'});
      act('d_gun_ici_unutulan',{RESPONSIBLE_ID:uid,COMPLETED:'N','>=DEADLINE':start,'<DEADLINE':cutoff});
      act('t_etkinlik',{AUTHOR_ID:uid,'>=CREATED':range.start30,'<CREATED':cutoff});
      act('t_acik',{RESPONSIBLE_ID:uid,COMPLETED:'N'});
      act('t_geciken',{RESPONSIBLE_ID:uid,COMPLETED:'N','>DEADLINE':'1970-01-01T00:00:00+03:00','<DEADLINE':cutoff});
      act('t_onceki_gun_geciken',{RESPONSIBLE_ID:uid,COMPLETED:'N','>DEADLINE':'1970-01-01T00:00:00+03:00','<DEADLINE':start});
      function lead(key,group,filter){add({userId:uid,key,method:'crm.lead.list',mode:'count',requires:'leadFields',stageGroup:group,body:{filter:{'@STATUS_ID':c[group],...filter},select:lf,order:{ID:'ASC'}}});}
      const movedDay={MOVED_BY_ID:uid,'>=MOVED_TIME':start,'<MOVED_TIME':cutoff};
      lead('d_randevu_son_hareket','randevuAsamalari',movedDay);
      lead('t_rand_portfoy','randevuAsamalari',{ASSIGNED_BY_ID:uid});
      lead('t_rand_son_hareket','randevuAsamalari',{MOVED_BY_ID:uid,'>=MOVED_TIME':range.start30,'<MOVED_TIME':cutoff});
      lead('d_satis_asamasi_son_hareket','satisAsamalari',movedDay);
      lead('t_satis_asamasi','satisAsamalari',{MOVED_BY_ID:uid});
      lead('d_donusen_son_hareket','donusumAsamalari',movedDay);
      lead('t_donusen','donusumAsamalari',{MOVED_BY_ID:uid});
    }
    s.warnings.push('Sonuçlar yalnızca seçili personel ve webhook kullanıcısının görebildiği Bitrix kayıtlarını kapsar.');
    s.warnings.push('CRM_TODO yapılacak işleri ölçülür; Bitrix Tasks görevleri, takvim veya diğer etkinlik türleri bu sayılara dahil değildir.');
    s.warnings.push('LAST_UPDATED tamamlama zamanı değildir. Tamamlayan kişi ve gerçek tamamlama tarihi bu kaynakla doğrulanamaz.');
    s.warnings.push('Lead listesi güncel aşamayı ve son hareketi gösterir; bütün tarihsel aşama geçişlerini veya gerçekleşen randevuları göstermez.');
    s.warnings.push('CONVERTED ayrı raporlanır; dönüşüm ve satış aşaması etiketi, tahsil edilmiş/gerçekleşmiş satış kanıtı değildir.');
    s.warnings.push('200, PBX başarılı çağrı kaydıdır; insanla konuşulduğunu kanıtlamaz. Arama kayıt adedi tekil müşteri/tekil çağrı oturumu değildir.');
    if(range.historical) s.warnings.push('Geçmiş rapor günü seçildi: açık işler ve portföy geçmiş gün sonunu değil, bugünkü sorgu durumunu gösterir.');
    return s;
  }
  function blankCurrent(){return {cursor:0,pages:0,attempt:0,seen:{},rows:[],totals:[],duplicates:0,rawRows:0};}
  function dependencyError(s,j){
    if (s.fatal) return s.fatal;
    if (s.blockedMethods[j.method]) return s.blockedMethods[j.method];
    if (j.userId && !s.people.find(p=>p.user_id===j.userId)?.verified) return 'USER_NOT_VERIFIED';
    if (j.requires) {
      const m=s.meta[j.requires];
      if(!m || m.status!=='ok') return 'FIELDS_NOT_VERIFIED';
      const required=unique([...Object.keys(j.body.filter||{}).map(k=>k.replace(/^[><=@!]+/,'')),...(j.body.select||[])]);
      if(required.some(k=>!m.fields.includes(k))) return 'REQUIRED_FIELD_MISSING';
    }
    if(j.stageGroup){
      const m=s.meta.stages;
      if(!m || m.status!=='ok') return 'STAGES_NOT_VERIFIED';
      if(s.config[j.stageGroup].some(id=>!m.values.some(r=>r.STATUS_ID===id))) return 'STAGE_ID_NOT_FOUND';
    }
    return null;
  }
  function outcome(s,j,data){
    const record={job:j.key,userId:j.userId||null,method:j.method,status:data.status,source:data.source||null,pages:s.current?.pages||0,rows:s.current?.rows.length||0,apiTotals:s.current?.totals||[],duplicates:s.current?.duplicates||0,error:data.error||null,checkedAt:s.lastResponseAt||null};
    s.audit.push(record);
    if(!j.userId){s.meta[j.key]={...data};}
    else {
      const p=s.people.find(p=>p.user_id===j.userId);
      if(j.key==='dailyCalls')p.calls={...data}; else p.metrics[j.key]={...data};
    }
    s.jobIndex++; s.current=null;
  }
  function prepare(state){
    const s=clone(state);
    while(s.jobIndex<s.jobs.length){
      const j=s.jobs[s.jobIndex];
      let reason=dependencyError(s,j);
      if(s.requestCount>=s.config.maxRequests) reason='REQUEST_BUDGET_EXCEEDED';
      if(reason){outcome(s,j,{value:null,status:'unavailable',error:reason});continue;}
      if(!READ_METHODS.includes(j.method))throw new Error('Salt okunur yöntem listesinin dışında çağrı engellendi.');
      if(!s.current)s.current=blankCurrent();
      s.current.attempt++; s.requestCount++;
      s.request={method:j.method,body:{...clone(j.body)}};
      if(j.mode!=='fields')s.request.body.start=s.current.cursor;
      s.done=false;
      return s;
    }
    s.done=true; delete s.request;
    return s;
  }
  function safeCode(x,fallback='API_ERROR'){
    return typeof x==='string' && /^[A-Za-z][A-Za-z0-9_-]{0,79}$/.test(x) ? x : fallback;
  }
  function normalizeResponse(raw){
    const status=nonNegInt(raw?.statusCode)?Number(raw.statusCode):200;
    const headers=raw?.headers&&typeof raw.headers==='object'?raw.headers:{};
    let body=own(raw,'body')?raw.body:raw;
    if(typeof body==='string'){
      try{body=JSON.parse(body);}catch{return {ok:false,status,headers,error:'INVALID_JSON'};}
    }
    if(!body || typeof body!=='object' || Array.isArray(body))return {ok:false,status,headers,error:'INVALID_RESPONSE'};
    if(status<200||status>=300||own(body,'error')||(!own(body,'result')&&body.error_description))return {ok:false,status,headers,error:safeCode(body.error,status>=400?`HTTP_${status}`:'TRANSPORT_OR_API_ERROR')};
    if(!own(body,'result'))return {ok:false,status,headers,error:'MISSING_RESULT'};
    return {ok:true,status,headers,body};
  }
  function retryDelay(s,r,nowISO){
    if(r.error==='OPERATION_TIME_LIMIT')return null;
    if(s.current.attempt>=s.config.maxAttempts)return null;
    const transient=[429,500,502,503,504].includes(r.status)||['QUERY_LIMIT_EXCEEDED','TOO_MANY_REQUESTS','INTERNAL_SERVER_ERROR','ERROR_UNEXPECTED_ANSWER','TRANSPORT_OR_API_ERROR','INVALID_JSON'].includes(r.error);
    if(!transient)return null;
    const hdr=Object.entries(r.headers||{}).find(([k])=>k.toLowerCase()==='retry-after')?.[1];
    let h=0;
    if(hdr!==undefined){h=/^\d+(\.\d+)?$/.test(String(hdr))?Math.ceil(Number(hdr)):Math.ceil((Date.parse(String(hdr))-Date.parse(nowISO))/1000);}
    if(Number.isFinite(h)&&h>120)return null; // Sunucunun uzun bekleme talebi ihlal edilmez; eksik veri raporlanır.
    return Math.max(s.config.requestIntervalSeconds,Math.min(60,2**s.current.attempt),Number.isFinite(h)?Math.max(0,h):0);
  }
  function rowProblem(j,row){
    if(!row||typeof row!=='object'||!posId(row.ID))return 'MISSING_OR_INVALID_ROW_ID';
    const filter=j.body.FILTER||j.body.filter||{};
    for(const [key,target] of Object.entries(filter)){
      const m=key.match(/^([><=@!]*)(.*)$/),op=m[1]||'=',field=m[2];
      const val=row[field];
      if(!own(row,field)||val===null||val===undefined)return 'FILTER_FIELD_MISSING';
      if(op==='@'||Array.isArray(target)){
        if(!target.map(String).includes(String(val)))return 'FILTER_SCOPE_MISMATCH';
      }else if(['>','>=','<','<='].includes(op)){
        const v=time(val),t=time(target);
        if(v===null||t===null)return 'INVALID_OR_UNZONED_DATE';
        if((op==='>'&&!(v>t))||(op==='>='&&!(v>=t))||(op==='<'&&!(v<t))||(op==='<='&&!(v<=t)))return 'FILTER_DATE_MISMATCH';
      }else if(String(val)!==String(target))return 'FILTER_SCOPE_MISMATCH';
    }
    return null;
  }
  function compact(j,row){
    if(j.mode==='calls')return Object.fromEntries(['ID','PORTAL_USER_ID','CALL_START_DATE','CALL_TYPE','CALL_FAILED_CODE','CALL_DURATION'].map(k=>[k,row[k]??null]));
    if(j.mode==='users')return {ID:String(row.ID),NAME:String(row.NAME||''),LAST_NAME:String(row.LAST_NAME||''),ACTIVE:row.ACTIVE??null};
    if(j.mode==='stages')return {ID:String(row.ID),ENTITY_ID:String(row.ENTITY_ID),STATUS_ID:String(row.STATUS_ID||''),NAME:String(row.NAME||''),SEMANTICS:row.SEMANTICS??null};
    return {ID:String(row.ID)};
  }
  function callMetrics(rows){
    const v=Object.fromEntries(CALL_KEYS.map(k=>[k,0]));
    let invalidDuration=0;
